//! Benchmark Runner - Load and execute synthetic SIW workloads
//!
//! Reads binary SIW files generated by siw-gen and measures performance.

use std::fs::File;
use std::io::Read;
use std::path::PathBuf;
use std::time::Instant;
use std::hint::black_box;
use vtpu_runtime::{SIW, DenseOp, SparseOp, CoordOp};

const CPU_FREQ_GHZ: f64 = 4.0; // AMD R9 8945HS base frequency

fn load_siw_file(path: &PathBuf) -> std::io::Result<Vec<SIW>> {
    let mut file = File::open(path)?;
    let mut buffer = Vec::new();
    file.read_to_end(&mut buffer)?;

    let siw_size = std::mem::size_of::<SIW>();
    if buffer.len() % siw_size != 0 {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            format!("File size {} not aligned to SIW size {}", buffer.len(), siw_size),
        ));
    }

    let count = buffer.len() / siw_size;
    let mut siws = Vec::with_capacity(count);

    for i in 0..count {
        let offset = i * siw_size;
        let siw_bytes = &buffer[offset..offset + siw_size];
        
        // SAFETY: SIW is repr(C, align(64)) and we validated alignment
        let siw = unsafe {
            std::ptr::read(siw_bytes.as_ptr() as *const SIW)
        };
        
        siws.push(siw);
    }

    Ok(siws)
}

/// Execute D-Pipe operation
#[inline(never)]
fn execute_d_pipe(op: &DenseOp, regs: &mut [i64; 32]) {
    match op {
        DenseOp::DADD { rd, rs1, rs2 } => {
            regs[*rd as usize] = black_box(regs[*rs1 as usize]) + black_box(regs[*rs2 as usize]);
        }
        DenseOp::DSUB { rd, rs1, rs2 } => {
            regs[*rd as usize] = black_box(regs[*rs1 as usize]) - black_box(regs[*rs2 as usize]);
        }
        DenseOp::DMUL { rd, rs1, rs2 } => {
            regs[*rd as usize] = black_box(regs[*rs1 as usize]) * black_box(regs[*rs2 as usize]);
        }
        DenseOp::DFMA { rd, rs1, rs2, rs3 } => {
            let a = black_box(regs[*rs1 as usize]);
            let b = black_box(regs[*rs2 as usize]);
            let c = black_box(regs[*rs3 as usize]);
            regs[*rd as usize] = a * b + c;
        }
        DenseOp::DMOV { rd, imm } => {
            regs[*rd as usize] = black_box(*imm);
        }
        DenseOp::DNOP => {}
        _ => {} // Other ops not critical for benchmarking
    }
}

/// Execute S-Pipe operation
#[inline(never)]
fn execute_s_pipe(op: &SparseOp, regs: &mut [i64; 32], mem: &mut Vec<i64>, coord_idx: usize) {
    match op {
        SparseOp::SGATHER { rd, width, .. } => {
            let idx = coord_idx % mem.len();
            regs[*rd as usize] = black_box(mem[idx]) + black_box(*width as i64);
        }
        SparseOp::SSCATTR { rs, width, .. } => {
            let idx = coord_idx % mem.len();
            mem[idx] = black_box(regs[*rs as usize]) + black_box(*width as i64);
        }
        SparseOp::SPREFCH { .. } => {
            let idx = coord_idx % mem.len();
            black_box(mem[idx]);
        }
        SparseOp::SNOP => {}
        _ => {}
    }
}

/// Execute C-Pipe operation
#[inline(never)]
fn execute_c_pipe(op: &CoordOp, barrier_count: &mut u64) {
    match op {
        CoordOp::CBAR { barrier_id, count } => {
            *barrier_count = black_box(*barrier_count + 1);
            black_box(barrier_id);
            black_box(count);
        }
        CoordOp::CNOP => {}
        _ => {}
    }
}

/// Execute a single SIW
#[inline(never)]
fn execute_siw(siw: &SIW, regs: &mut [i64; 32], mem: &mut Vec<i64>, 
               coord_idx: usize, barrier_count: &mut u64) {
    execute_d_pipe(&siw.d_op, regs);
    execute_s_pipe(&siw.s_op, regs, mem, coord_idx);
    execute_c_pipe(&siw.c_op, barrier_count);
    black_box(siw);
}

fn benchmark_workload(name: &str, siws: &[SIW]) {
    let mut regs = [0i64; 32];
    regs[1] = 42;
    regs[2] = 10;
    regs[3] = 5;
    
    let mut mem = vec![0i64; 1024]; // 8KB working set
    let mut barrier_count = 0u64;
    
    // Warmup
    for (idx, siw) in siws.iter().enumerate() {
        execute_siw(siw, &mut regs, &mut mem, idx, &mut barrier_count);
    }
    
    // Timed run
    let start = Instant::now();
    for (idx, siw) in siws.iter().enumerate() {
        execute_siw(siw, &mut regs, &mut mem, idx, &mut barrier_count);
    }
    let elapsed = start.elapsed();
    
    // Prevent optimization
    black_box(regs);
    black_box(mem);
    black_box(barrier_count);
    
    // Calculate metrics
    let count_active_ops = siws.iter().map(|siw| {
        let mut ops = 0;
        if !matches!(siw.d_op, DenseOp::DNOP) { ops += 1; }
        if !matches!(siw.s_op, SparseOp::SNOP) { ops += 1; }
        if !matches!(siw.c_op, CoordOp::CNOP) { ops += 1; }
        ops
    }).sum::<usize>();
    
    let elapsed_ns = elapsed.as_nanos() as f64;
    let elapsed_cycles = elapsed_ns * CPU_FREQ_GHZ; // ns * GHz = cycles
    let ops_per_cycle = count_active_ops as f64 / elapsed_cycles;
    
    println!("{:<25} {:>8} SIWs  {:>10} ops  {:>8.2} ms  {:>6.3} ops/cycle",
             name,
             siws.len(),
             count_active_ops,
             elapsed.as_secs_f64() * 1000.0,
             ops_per_cycle);
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("vTPU Benchmark Runner");
    println!("AMD Zen 4 @ {:.1} GHz (assumed)\n", CPU_FREQ_GHZ);
    println!("{:<25} {:>8}       {:>10}       {:>8}     {:>6}",
             "Workload", "SIWs", "Active Ops", "Time", "Ops/Cyc");
    println!("{}", "-".repeat(75));
    
    let workloads = [
        ("D-Heavy (High Locality)", "benchmarks/workloads/d-heavy-high.siw"),
        ("D-Heavy (Low Locality)", "benchmarks/workloads/d-heavy-low.siw"),
        ("S-Heavy (High Locality)", "benchmarks/workloads/s-heavy-high.siw"),
        ("S-Heavy (Low Locality)", "benchmarks/workloads/s-heavy-low.siw"),
        ("C-Heavy (Medium)", "benchmarks/workloads/c-heavy-medium.siw"),
        ("Balanced (Medium)", "benchmarks/workloads/balanced-medium.siw"),
        ("Balanced (Low + Deep)", "benchmarks/workloads/balanced-low-deep.siw"),
    ];
    
    for (name, path) in &workloads {
        match load_siw_file(&PathBuf::from(path)) {
            Ok(siws) => benchmark_workload(name, &siws),
            Err(e) => eprintln!("Failed to load {}: {}", name, e),
        }
    }
    
    println!("\n✅ Benchmark complete");
    println!("Target: 2.5+ ops/cycle for Phase 1 PoC");
    
    Ok(())
}
